package io.atlas.modules.research.service;
import io.atlas.modules.research.repository.ResearchRepository;
import io.atlas.modules.research.repository.ResearchRepository.*;
import io.atlas.modules.auth.AuthModule;
import io.atlas.modules.research.model.ResearchPlan;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.network.chat.Component;
import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;
public final class ResearchService {
 private final ResearchRepository repository=new ResearchRepository();private final ResearchMoneyService money=new ResearchMoneyService();
 private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor(r->{var t=new Thread(r,"atlas-research");t.setDaemon(true);return t;});private MinecraftServer server;
 private final Map<UUID,Capture> pendingCaptures=new ConcurrentHashMap<>();
 private void record(Capture capture){try{if(repository.record(capture))cache.remove(capture.player());pendingCaptures.remove(capture.pokemon());}catch(Exception e){io.atlas.AtlasMod.LOGGER.warn("Captura de pesquisa {} aguardando persistência",capture.pokemon(),e);}}
 private record Cached(Summary value,long until){}private final Map<UUID,Cached> cache=new ConcurrentHashMap<>();private final Set<UUID> busy=ConcurrentHashMap.newKeySet();
 public void start(MinecraftServer server){this.server=server;worker.scheduleWithFixedDelay(this::poll,5,5,TimeUnit.SECONDS);}
 private ServerPlayer player(UUID id){var p=server.getPlayerList().getPlayer(id);return p!=null&&!p.hasDisconnected()&&AuthModule.getAuthService().isAuthenticated(id)?p:null;}
 private <T>T main(Supplier<T> action)throws Exception{var f=new CompletableFuture<T>();server.execute(()->{try{f.complete(action.get());}catch(Throwable e){f.completeExceptionally(e);}});return f.get(20,TimeUnit.SECONDS);}
 private void message(UUID id,String text){server.execute(()->{var p=player(id);if(p!=null)p.sendSystemMessage(Component.literal(text));});}
 public void captured(com.cobblemon.mod.common.api.events.pokemon.PokemonCapturedEvent event){var p=event.getPlayer();if(server==null||!AuthModule.getAuthService().isAuthenticated(p.getUUID())||p.isCreative()||p.isSpectator())return;String world=p.serverLevel().dimension().location().toString();if(!Set.of("atlas:survival_emerald","minecraft:the_nether","minecraft:the_end").contains(world))return;var pokemon=event.getPokemon();var types=new ArrayList<String>();for(var type:pokemon.getTypes())types.add(type.getName());var data=new Capture(pokemon.getUuid(),p.getUUID(),pokemon.getSpecies().getResourceIdentifier().toString(),List.copyOf(types),System.currentTimeMillis());pendingCaptures.putIfAbsent(data.pokemon(),data);worker.execute(()->record(data));}
 public int open(ServerPlayer player,String track){if(!AuthModule.getAuthService().isAuthenticated(player.getUUID())||!busy.add(player.getUUID()))return 0;UUID id=player.getUUID();worker.execute(()->{try{var cached=cache.get(id);var summary=cached!=null&&cached.until()>System.currentTimeMillis()?cached.value():repository.summary(id);cache.put(id,new Cached(summary,System.currentTimeMillis()+5000));server.execute(()->{var p=player(id);if(p!=null)p.openMenu(new net.minecraft.world.SimpleMenuProvider((menu,inventory,viewer)->new io.atlas.modules.research.menu.ResearchMenu(menu,inventory,summary,track),Component.literal("Pesquisas Pokémon")));});}catch(Exception e){message(id,"§cPesquisas temporariamente indisponíveis.");io.atlas.AtlasMod.LOGGER.warn("Falha ao abrir pesquisas",e);}finally{busy.remove(id);}});return 1;}
 public void claim(ServerPlayer player,String track,int stage){if(!AuthModule.getAuthService().isAuthenticated(player.getUUID())||!busy.add(player.getUUID()))return;UUID id=player.getUUID();player.closeContainer();worker.execute(()->{try{var payment=repository.claim(id,track,stage);cache.remove(id);message(id,payment.isPresent()?"§aPagamento solicitado. Consulte /saldo ou /pesquisas.":"§cEtapa ainda não disponível ou já resgatada.");}catch(Exception e){message(id,"§cNão foi possível solicitar o pagamento.");io.atlas.AtlasMod.LOGGER.warn("Falha ao solicitar pagamento de pesquisa",e);}finally{busy.remove(id);}});}
 private void poll(){try{for(var capture:List.copyOf(pendingCaptures.values()))record(capture);for(var payment:repository.pending()){try{if(!main(()->player(payment.player())!=null))continue;boolean recovery=payment.state().equals("PAYING");if(!recovery&&!repository.transition(payment.id(),"PENDING","PAYING"))continue;boolean paid=main(()->{var p=player(payment.player());if(p==null)return false;try{return money.pay(p,payment,recovery);}catch(Exception e){throw new IllegalStateException(e);}});if(!paid){if(!recovery)repository.transition(payment.id(),"PAYING","PENDING");continue;}if(repository.transition(payment.id(),"PAYING","PAID")){cache.remove(payment.player());message(payment.player(),"§aPesquisa concluída! Você recebeu §f"+io.atlas.modules.economy.EconomyService.format(java.math.BigInteger.valueOf(payment.amount()))+" CobbleDollars§a.");}}catch(Exception e){Throwable cause=e;while(cause.getCause()!=null)cause=cause.getCause();if("UNCERTAIN_PAYMENT".equals(cause.getMessage()))repository.transition(payment.id(),"PAYING","REVIEW");io.atlas.AtlasMod.LOGGER.warn("Pagamento de pesquisa {} preservado para retry/conferência",payment.id(),e);}}}catch(Exception e){io.atlas.AtlasMod.LOGGER.warn("Fila de pagamentos de pesquisa indisponível",e);}}
 public void remove(UUID id){cache.remove(id);}
 public void stop(){worker.shutdownNow();}
}
